    a5: 'Η τηλεϊατρική σου επιτρέπει να συνδεθείς με κτηνίατρο μέσω βιντεοκλήσης χωρίς να βγεις από το σπίτι. Ιδανική για συμβουλές, follow-up επισκέψεις και μη επείγουσες περιπτώσεις.',
    q6: 'Πώς λειτουργεί το AI Health Check;',
    a6: 'Ανεβάζεις φωτογραφία του κατοικιδίου σου (δέρμα, μάτια, αυτιά, περιττώματα) και η AI αναλύει για πιθανά προβλήματα υγείας. Δεν αντικαθιστά τον κτηνίατρο αλλά βοηθά στην έγκαιρη ανίχνευση.',
    q7: 'Μπορώ να ακυρώσω ραντεβού;',
    a7: 'Ναι. Η ακύρωση είναι δωρεάν έως 24 ώρες πριν το ραντεβού, με πλήρη επιστροφή των χρημάτων. Αν ακυρώσεις μέσα στις 24 ώρες, επιστρέφεται το 50% της αξίας. Αν ακυρώσει ο πάροχος, παίρνεις πάντα πίσω ολόκληρο το ποσό.',
    q8: 'Πώς γίνομαι πάροχος υπηρεσιών;',
    a8: 'Κάνε εγγραφή ως "Πάροχος Υπηρεσιών", συμπλήρωσε στοιχεία επιχείρησης, ανέβασε άδειες/πιστοποιήσεις. Μετά από έλεγχο (1-3 ημέρες) ενεργοποιείται το προφίλ σου.',
    q9: 'Πώς προστατεύονται τα δεδομένα μου;',
    a9: 'Η σύνδεση με την πλατφόρμα είναι πάντα κρυπτογραφημένη (HTTPS), τα ευαίσθητα στοιχεία, όπως το τηλέφωνο, αποθηκεύονται κρυπτογραφημένα, και τα δεδομένα φιλοξενούνται σε servers στην Ευρώπη. Τηρούμε τον GDPR. Δες την Πολιτική Απορρήτου για λεπτομέρειες.',
    q10: 'Σε ποιες χώρες λειτουργεί το GlobiPet;',
    a10: 'Αρχικά διαθέσιμο σε Ελλάδα και Κύπρο. Το 2027 επεκτεινόμαστε σε Ισπανία και Ηνωμένο Βασίλειο.',
