    intro: 'Καλώς ήρθες στο GlobiPet. Παρακάτω περιγράφονται οι όροι και προϋποθέσεις χρήσης της πλατφόρμας μας. Με την εγγραφή και χρήση του GlobiPet, συμφωνείς με τους ακόλουθους όρους.',
    s1Title: 'Αποδοχή Όρων',
