    s2Title: 'Περιγραφή Υπηρεσιών',
    s2Body: 'Το GlobiPet προσφέρει ψηφιακή πλατφόρμα διασύνδεσης ιδιοκτητών κατοικιδίων με παρόχους υπηρεσιών (κτηνιάτρους, groomers, εκπαιδευτές κλπ), τηλεϊατρική, AI εργαλεία υγείας, ηλεκτρονικό κατάστημα και κοινότητα.',
    s3Title: 'Δημιουργία Λογαριασμού',
