    s4Title: 'Υποχρεώσεις Χρηστών',
    s4Body: 'Οι χρήστες υποχρεούνται:\n• Να παρέχουν ακριβή στοιχεία\n• Να μη χρησιμοποιούν την πλατφόρμα για παράνομες δραστηριότητες\n• Να σέβονται τα δικαιώματα άλλων χρηστών και παρόχων\n• Να μη μοιράζονται τον λογαριασμό τους',
    s5Title: 'Πληρωμές & Επιστροφές',
    s5Body: 'Οι πληρωμές κρατήσεων, παραγγελιών, τηλεϊατρικής και εκδηλώσεων γίνονται μέσω Viva Payments και οι συνδρομές μέσω Stripe. Κρατήσεις και τηλεϊατρική: πλήρης επιστροφή αν ακυρώσεις έως 24 ώρες πριν, 50% αργότερα, καμία ακύρωση μετά την έναρξη· αν ακυρώσει ο πάροχος, πλήρης επιστροφή. Εκδηλώσεις: πλήρης επιστροφή έως 48 ώρες πριν. Για επιστροφές προϊόντων ισχύουν 14 ημέρες από την παραλαβή σύμφωνα με τη νομοθεσία.',
