    s6Body: 'Το GlobiPet ενεργεί ως πλατφόρμα διαμεσολάβησης. Οι πάροχοι είναι ανεξάρτητοι επαγγελματίες και είναι αποκλειστικά υπεύθυνοι για τις υπηρεσίες που παρέχουν. Το GlobiPet δεν φέρει ευθύνη για ιατρικές αποφάσεις.',
    s7Title: 'Πνευματικά Δικαιώματα',
    s7Body: 'Όλο το περιεχόμενο της πλατφόρμας (κείμενα, εικόνες, λογότυπα, λογισμικό) ανήκει στο GlobiPet ή στους δικαιούχους του. Απαγορεύεται η αναπαραγωγή χωρίς γραπτή άδεια.',
