  faq: {
    title: 'Frequently Asked Questions',
    subtitle: 'The most common questions from our users',
    q1: 'What is GlobiPet?',
    a1: 'GlobiPet is an integrated pet super-app combining veterinary services, telemedicine, product marketplace, AI health tools and pet owner community in one platform.',
    q2: 'How do I create an account?',
    a2: 'Click "Sign Up" at top right, fill in email, name and password. You can also sign in with Google. Registration is free.',
    q3: 'Is GlobiPet free to use?',
    a3: 'Yes, basic use is completely free. You only pay for services you book (e.g. vet, grooming) or products you purchase from the marketplace.',
    q4: 'How do I book a vet appointment?',
    a4: 'Go to Services → select Veterinarian → see available providers near you → pick a time → confirm. You receive instant confirmation and reminder before the appointment.',
    q5: 'What is telemedicine?',
    a5: 'Telemedicine lets you connect with a veterinarian via video call without leaving home. Ideal for consultations, follow-ups and non-emergency cases.',
    q6: 'How does AI Health Check work?',
    a6: 'Upload a photo of your pet (skin, eyes, ears, stool) and AI analyzes for potential health issues. Does not replace the vet but helps with early detection.',
    q7: 'Can I cancel appointments?',
    a7: 'Yes. Cancellation is free up to 24 hours before the appointment, with a full refund. If you cancel within 24 hours, 50% of the amount is refunded. If the provider cancels, you always get the full amount back.',
    q8: 'How do I become a service provider?',
    a8: 'Sign up as "Service Provider", fill business details, upload licenses/certifications. After review (1-3 days) your profile is activated.',
    q9: 'How is my data protected?',
    a9: 'Your connection to the platform is always encrypted (HTTPS), sensitive details such as your phone number are stored encrypted, and data is hosted on servers in Europe. We comply with the GDPR. See the Privacy Policy for details.',
    q10: 'Which countries does GlobiPet operate in?',
    a10: 'Initially available in Greece and Cyprus. In 2027 we are expanding to Spain and the United Kingdom.',
  },
