  faq: {
    title: 'Questions Fréquentes',
    subtitle: 'Les questions les plus courantes de nos utilisateurs',
    q1: 'Qu\'est-ce que GlobiPet?',
    a1: 'GlobiPet est une super-app intégrée pour animaux combinant services vétérinaires, télémédecine, marketplace de produits, outils IA santé et communauté de propriétaires en une plateforme.',
    q2: 'Comment créer un compte?',
    a2: 'Cliquez "S\'inscrire" en haut à droite, remplissez email, nom et mot de passe. Vous pouvez aussi vous connecter avec Google. L\'inscription est gratuite.',
    q3: 'GlobiPet est-il gratuit?',
    a3: 'Oui, l\'utilisation basique est entièrement gratuite. Vous ne payez que pour les services réservés (vétérinaire, toilettage) ou produits du marketplace.',
    q4: 'Comment réserver un vétérinaire?',
    a4: 'Allez dans Services → sélectionnez Vétérinaire → voyez les prestataires proches → choisissez heure → confirmez. Confirmation instantanée et rappel avant rendez-vous.',
    q5: 'Qu\'est-ce que la télémédecine?',
    a5: 'La télémédecine vous permet de vous connecter à un vétérinaire par appel vidéo sans sortir. Idéale pour consultations, suivis et cas non urgents.',
    q6: 'Comment fonctionne AI Health Check?',
    a6: 'Téléchargez une photo de votre animal (peau, yeux, oreilles, selles) et l\'IA analyse les problèmes potentiels. Ne remplace pas le vétérinaire mais aide à la détection précoce.',
    q7: 'Puis-je annuler des rendez-vous?',
    a7: 'Oui. L’annulation est gratuite jusqu’à 24 heures avant le rendez-vous, avec remboursement intégral. Si vous annulez dans les 24 heures, 50 % du montant est remboursé. Si le prestataire annule, vous êtes toujours remboursé intégralement.',
    q8: 'Comment devenir prestataire?',
    a8: 'Inscrivez-vous comme "Prestataire", remplissez les détails business, téléchargez licences/certifications. Après vérification (1-3 jours) votre profil est activé.',
    q9: 'Comment mes données sont protégées?',
    a9: 'La connexion à la plateforme est toujours chiffrée (HTTPS), les données sensibles comme le téléphone sont stockées chiffrées et les données sont hébergées sur des serveurs en Europe. Nous respectons le RGPD. Consultez la Politique de confidentialité pour plus de détails.',
    q10: 'Dans quels pays opère GlobiPet?',
    a10: 'Disponible d’abord en Grèce et à Chypre. En 2027, nous nous étendons à l’Espagne et au Royaume-Uni.',
  },
