    lastUpdated: 'Dernière mise à jour',
    updatedDate: '21 octobre 2026',
    intro: 'Bienvenue sur GlobiPet. Voici les conditions d\'utilisation de notre plateforme. En vous inscrivant et utilisant GlobiPet, vous acceptez ces conditions.',
    s1Title: 'Acceptation des Conditions',
    s1Body: 'En accédant et utilisant les services GlobiPet, vous acceptez inconditionnellement toutes ces conditions. Si vous n\'êtes pas d\'accord, n\'utilisez pas la plateforme.',
    s2Title: 'Description du Service',
    s2Body: 'GlobiPet fournit une plateforme numérique connectant propriétaires d\'animaux et prestataires (vétérinaires, toiletteurs, dresseurs), télémédecine, outils IA santé, boutique en ligne et communauté.',
    s3Title: 'Création de Compte',
    s3Body: 'Pour utiliser nos services, créez un compte avec informations précises et à jour. Vous êtes responsable de la sécurité du mot de passe et toutes actions depuis votre compte.',
    s4Title: 'Obligations Utilisateur',
    s4Body: 'Les utilisateurs doivent:\n• Fournir informations précises\n• Ne pas utiliser la plateforme pour activités illégales\n• Respecter droits d\'autres utilisateurs et prestataires\n• Ne pas partager leur compte',
    s5Title: 'Paiements et Remboursements',
    s5Body: 'Les paiements des réservations, commandes, télésanté et événements passent par Viva Payments, et les abonnements par Stripe. Réservations et télésanté : remboursement intégral si vous annulez jusqu\'à 24 heures avant, 50 % ensuite, aucune annulation après le début ; si le prestataire annule, remboursement intégral. Événements : remboursement intégral jusqu\'à 48 heures avant. Les retours de produits sont acceptés sous 14 jours à compter de la réception, conformément à la loi.',
    s6Title: 'Prestataires de Services',
    s6Body: 'GlobiPet agit comme plateforme intermédiaire. Les prestataires sont des professionnels indépendants seuls responsables des services. GlobiPet n\'est pas responsable des décisions médicales.',
    s7Title: 'Propriété Intellectuelle',
    s7Body: 'Tout le contenu de la plateforme (textes, images, logos, logiciels) appartient à GlobiPet ou ses ayants droit. Reproduction sans permission écrite interdite.',
    s8Title: 'Limitation de Responsabilité',
    s8Body: 'GlobiPet est fourni "tel quel". Nous ne garantissons pas un fonctionnement ininterrompu ou sans erreur. Notre responsabilité est limitée au maximum permis par la loi.',
    s9Title: 'Modification des Conditions',
    s9Body: 'Nous nous réservons le droit de modifier les conditions à tout moment. Changements importants communiqués par email. L\'utilisation continue après modification constitue acceptation.',
    s10Title: 'Loi Applicable',
    s10Body: 'Ces conditions sont régies par le droit grec. Les tribunaux d\'Athènes sont désignés compétents. Nous cherchons à résoudre les différends à l\'amiable.',
    contactNote: 'Pour questions sur les conditions contactez',
